"""Create a pull request with an auto-generated, diff-based description.

Used by AI agents (and humans) at the end of a feature/bugfix/testgen/refactor
run. The description is generated by a Cursor cloud agent from the diff, then
the PR is opened via `gh pr create`.

Usage:

    python scripts/create_pr.py \\
        --base main \\
        --head feat/add-mqtt-retry \\
        --title "feat(collector): retry MQTT publishes" \\
        --label trivial

If CURSOR_API_KEY is set, the body is generated from the diff; otherwise a
template body is used (summary + file list).

Exit codes:
    0  PR created (or already existed)
    1  startup failure (gh missing, not on a branch, etc.)
"""

from __future__ import annotations

import argparse
import os
import subprocess
import sys

BODY_PROMPT = """\
You write pull-request descriptions for the BDX-Intelligence project.

Given the diff below, produce a Markdown PR body with these sections:
  ## Summary
  One paragraph: what and why.
  ## Changes
  Bullet list of the meaningful changes (file: what changed).
  ## Tests
  How the change is tested (test names added/updated, coverage delta if known).
  ## Risk
  One line: "low" / "medium" + reason. If the diff touches sap_sl/, db/, or
  alembic/, say "needs CODEOWNER review".

Be concise. Do not invent facts not present in the diff. Do not write code.
"""


def _git(*args: str) -> str:
    return subprocess.run(["git", *args], check=True, capture_output=True, text=True).stdout.strip()


def _diff(base: str, head: str) -> str:
    return _git("diff", f"{base}...{head}")


def _generate_body(diff: str) -> str:
    if not os.environ.get("CURSOR_API_KEY"):
        files = _git("diff", "--name-only", "HEAD~1") or "(uncommitted)"
        return (
            "## Summary\n\n_Auto-generated placeholder — set `CURSOR_API_KEY` "
            "for an AI-generated description._\n\n"
            "## Changes\n\n"
            + "\n".join(f"- `{f}`" for f in files.splitlines())
            + "\n\n## Tests\n\n_To be filled in._\n\n## Risk\n\n_To be filled in._\n"
        )
    try:
        from cursor_sdk import Agent, AgentOptions, CloudAgentOptions
    except ImportError:
        return "_cursor-sdk not installed — placeholder body._"
    prompt = f"{BODY_PROMPT}\n\nDIFF:\n```diff\n{diff[:200000]}\n```\n"
    try:
        result = Agent.prompt(
            prompt,
            AgentOptions(
                api_key=os.environ["CURSOR_API_KEY"],
                model="composer-2.5",
                cloud=CloudAgentOptions(repos=[]),
            ),
        )
        return result.result or "_no body generated._"
    except Exception as exc:
        return f"_body generation failed: {exc}_"


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--base", default="main")
    parser.add_argument("--head", required=True)
    parser.add_argument("--title", required=True)
    parser.add_argument("--label", action="append", default=[])
    args = parser.parse_args()

    diff = _diff(args.base, args.head)
    if not diff.strip():
        print("No diff between base and head — nothing to PR.", file=sys.stderr)
        return 1

    body = _generate_body(diff)

    cmd = [
        "gh",
        "pr",
        "create",
        "--base",
        args.base,
        "--head",
        args.head,
        "--title",
        args.title,
        "--body",
        body,
    ]
    for label in args.label:
        cmd += ["--label", label]
    try:
        out = subprocess.run(cmd, check=True, capture_output=True, text=True)
    except subprocess.CalledProcessError as exc:
        # PR already exists is not a hard failure.
        if "already exists" in (exc.stderr or "").lower():
            print("PR already exists — nothing to do.")
            return 0
        print(f"gh pr create failed: {exc.stderr}", file=sys.stderr)
        return 1
    print(out.stdout.strip())
    return 0


if __name__ == "__main__":
    sys.exit(main())
